export function createAdapter() {
  return {
    prepare({ testCase, inputs }) {
      if (testCase.operation !== "matrixVectorMultiply" || !inputs.leftMatrix) return null;
      const matrix = inputs.leftMatrix.data;
      const vector = inputs.vector;
      const rows = inputs.leftMatrix.rows;
      const columns = inputs.leftMatrix.columns;
      return {
        execute() {
          let first = 0;
          for (let row = 0; row < rows; row += 1) {
            let sum = 0;
            const offset = row * columns;
            for (let column = 0; column < columns; column += 1) sum += matrix[offset + column] * vector[column];
            if (row === 0) first = sum;
          }
          return first;
        },
        densityActual: testCase.densityRequested,
        nnz: 0,
        ellpackStorageSlots: 0,
        ellpackPaddingRatio: 0,
        estimatedMemoryBytes: matrix.byteLength + vector.byteLength
      };
    }
  };
}
